INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Kundenbeziehungen > Kundengespräche > Vorbereiten
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist es bei der Vorbereitung eines Kundengesprächs ausreichend, nur die technischen Anforderungen zu kennen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kundenziele und Kontext sind entscheidend"}, {"text": "Ja", "correct": false, "because": "Technik allein reicht nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss bei der Vorbereitung eines Kundengesprächs ein Gesprächsleitfaden zwingend schriftlich erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Mentale Struktur kann genügen, ist aber riskant"}, {"text": "Ja", "correct": false, "because": "Schriftform ist nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Vorbereitung eines Kundengesprächs die rechtlichen Rahmenbedingungen des Projekts ignorieren?', 2, '[{"text": "Nein", "correct": true, "because": "Rechtliche Aspekte wie DSGVO sind essenziell"}, {"text": "Ja", "correct": false, "because": "Rechtliche Ignoranz führt zu Problemen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es bei der Vorbereitung eines Kundengesprächs notwendig, mögliche Einwände des Kunden zu antizipieren?', 2, '[{"text": "Ja", "correct": true, "because": "Voraussicht erhöht Gesprächserfolg"}, {"text": "Nein", "correct": false, "because": "Antizipation ist strategisch wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Reicht es bei der Vorbereitung eines Kundengesprächs, sich nur auf die eigenen Produkte zu konzentrieren?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenbedürfnisse stehen im Fokus"}, {"text": "Ja", "correct": false, "because": "Produktfixierung vernachlässigt den Kunden"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Vorbereitung eines Kundengesprächs am wichtigsten, um Missverständnisse zu vermeiden?', 2, '[{"text": "Klare Zieldefinition", "correct": true, "because": "Ziele steuern das Gespräch"}, {"text": "Technische Präsentation", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Kostenübersicht", "correct": false, "because": "Details folgen später"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationsquelle sollte primär genutzt werden, um sich auf ein Kundengespräch vorzubereiten?', 3, '[{"text": "Kundenspezifische Daten", "correct": true, "because": "CRM-Daten geben Kontext"}, {"text": "Allgemeine Branchentrends", "correct": false, "because": "Zu unspezifisch"}, {"text": "Eigene Produktbeschreibungen", "correct": false, "because": "Kundenorientierung fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element sollte bei der Vorbereitung eines Kundengesprächs nicht fehlen?', 2, '[{"text": "Agenda", "correct": true, "because": "Strukturiert das Gespräch"}, {"text": "Marketingflyer", "correct": false, "because": "Nice-to-have, nicht essenziell"}, {"text": "Preisliste", "correct": false, "because": "Verhandlungsdetail"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Vorbereitung eines Kundengesprächs?', 2, '[{"text": "Kundenzufriedenheit sichern", "correct": true, "because": "Fokus auf Kundenbedarf"}, {"text": "Schnellen Vertragsabschluss", "correct": false, "because": "Zu kurzfristig gedacht"}, {"text": "Technische Überlegenheit zeigen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler in der Vorbereitung eines Kundengesprächs kann rechtliche Konsequenzen haben?', 2, '[{"text": "Ignorieren von Datenschutzvorgaben", "correct": true, "because": "DSGVO-Verstoß möglich"}, {"text": "Fehlende Produktkenntnisse", "correct": false, "because": "Ärgerlich, aber nicht rechtlich"}, {"text": "Unklare Zeitplanung", "correct": false, "because": "Organisatorisch, nicht rechtlich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten bei der Vorbereitung eines Kundengesprächs berücksichtigt werden?', 4, '[{"text": "Kundenanforderungen", "correct": true, "because": "Grundlage des Gesprächs"}, {"text": "Rechtliche Rahmenbedingungen", "correct": true, "because": "Compliance ist Pflicht"}, {"text": "Eigene Ziele", "correct": true, "because": "Steuerung des Ergebnisses"}, {"text": "Wettervorhersage", "correct": false, "because": "Irrelevant für Gespräch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen sollten vor einem Kundengespräch gesammelt werden?', 3, '[{"text": "Frühere Kundeninteraktionen", "correct": true, "because": "Kontext ist entscheidend"}, {"text": "Kundenbranche", "correct": true, "because": "Verständnis der Umgebung"}, {"text": "Konkurrenzanalyse", "correct": true, "because": "Positionierung hilft"}, {"text": "Kundenfavoriten im Sport", "correct": false, "because": "Nice-to-know, nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools können bei der Vorbereitung eines Kundengesprächs hilfreich sein?', 4, '[{"text": "CRM-System", "correct": true, "because": "Kundendaten strukturiert"}, {"text": "Projektmanagement-Software", "correct": true, "because": "Zeitplanung und Ziele"}, {"text": "Präsentationssoftware", "correct": true, "because": "Visualisierung von Inhalten"}, {"text": "Musik-Streaming-Dienst", "correct": false, "because": "Keine Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können durch unzureichende Vorbereitung eines Kundengesprächs entstehen?', 3, '[{"text": "Missverständnisse", "correct": true, "because": "Fehlende Klarheit"}, {"text": "Vertragsverzögerungen", "correct": true, "because": "Unklare Anforderungen"}, {"text": "Rechtliche Verstöße", "correct": true, "because": "Ignoranz von Vorschriften"}, {"text": "Technischer Defekt", "correct": false, "because": "Nicht Vorbereitungsproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fragen sollten bei der Vorbereitung eines Kundengesprächs geklärt werden?', 3, '[{"text": "Was sind die Kundenziele?", "correct": true, "because": "Fokus des Gesprächs"}, {"text": "Welche rechtlichen Grenzen gibt es?", "correct": true, "because": "Compliance sicherstellen"}, {"text": "Welche Einwände sind möglich?", "correct": true, "because": "Strategische Vorbereitung"}, {"text": "Welches Mittagessen bevorzugt der Kunde?", "correct": false, "because": "Irrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Vorbereitung eines Kundengesprächs sollte die Kundenbranche berücksichtigen. b) Rechtliche Aspekte sind bei der Vorbereitung irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Branche ja, Recht ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Gesprächsleitfaden ist bei der Vorbereitung optional. b) Die Kundenanforderungen müssen immer schriftlich vorliegen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leitfaden optional, Anforderungen flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Vorbereitung eines Kundengesprächs sollte mögliche Einwände antizipieren. b) Eine Agenda ist rechtlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einwände ja, Agenda nicht rechtlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Vorbereitung eines Kundengesprächs dient nur der eigenen Sicherheit. b) Kundendaten aus dem CRM sind hilfreich.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Sicherheit nicht allein, CRM ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Vorbereitung eines Kundengesprächs sollte die DSGVO berücksichtigen. b) Eine unzureichende Vorbereitung kann Vertragsstrafen auslösen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO ja, Strafen nicht direkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht zwangsläufig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

